    // Подсветки «успех»/«тревога» тоже без заливки: фон страницы не наш.
    $т['тревога'] = 'none'; $т['успех'] = 'none';
    $т['маркер'] = ['точка' => 'disc', 'стрелка' => "'▸  '", 'квадрат' => 'square', 'тире' => "'—  '", 'ромб' => "'◆  '", 'галка' => "'✓  '", 'звезда' => "'★  '"][$т['список']] ?? 'disc';
